    [DataContract]public sealed class ControlCenterOptions {
        [DataMember]public bool Enabled=true,Locked,Topmost,Motion=true;
        [DataMember]public bool ShowControl=true,ShowTray=true,ShowStart=true;
        [DataMember]public double? Left,Top;
        [DataMember]public double Size=54,Opacity=80,IconSize=26,PanelIconSize=24;
        [DataMember]public string IconStyle="switches";
        [DataMember]public string Color="#A9C9FF";
        [OnDeserializing]void Defaults(StreamingContext context){Enabled=true;Motion=true;ShowControl=ShowTray=ShowStart=true;Size=54;Opacity=80;IconSize=26;PanelIconSize=24;IconStyle="switches";Color="#A9C9FF";}
        public void Normalize(){IconSize=LayoutRules.Clamp(IconSize,12,72,26);PanelIconSize=LayoutRules.Clamp(PanelIconSize,12,36,24);IconStyle=ControlIconRules.Style(IconStyle);Size=LayoutRules.Clamp(Size,36,100,54);Opacity=LayoutRules.Clamp(Opacity,15,100,80);if(Left.HasValue&&(double.IsNaN(Left.Value)||double.IsInfinity(Left.Value)))Left=null;if(Top.HasValue&&(double.IsNaN(Top.Value)||double.IsInfinity(Top.Value)))Top=null;string color=WidgetStyle.Color(Color);Color=string.IsNullOrEmpty(color)?"#A9C9FF":color;}
    }
    public static class ControlIconRules {
        public static readonly string[] Styles={"switches","tiles","spark"};
        public static readonly string[] Names={"圆角双拨杆","四格面板","四瓣星芒"};
        public static string Style(string value){return Array.IndexOf(Styles,value)<0?Styles[0]:value;}
        public static double OrbGlyphSize(ControlCenterOptions options){return Math.Min(options.IconSize,options.Size-12);}
    }
